import os
from typing import List, Optional

from taf.rfrl.utilities.robot.RobotWrapper import RobotWrapper

from taf.rfrl.csv4all.resources.test_cases.csv4all_test import IterationFailedError
from taf.rfrl.csv4all.resources.test_cases.exceptions import TestFailedOnTeardownError, TestExecutionFailed, \
    RecoveryAttemptFailedError
from taf.rfrl.csv4all.resources.test_cases.upgrade_test import UpgradeTest
from taf.rfrl.csv4all.resources.node.exceptions import WrongSwVersion
from taf.rfrl.csv4all.resources.utilities.decorators import method_decorator, wrapper_decorator
from taf.rfrl.csv4all.resources.utilities.exceptions import FatalError
from taf.rfrl.csv4all.resources.utilities.utilities import test_logger


class UpgradeRollbackTest(UpgradeTest):

    def __init__(self, nodes_details: List[dict], test_nodes_details: List[dict], iterations_per_node: int,
                 report: bool, calculate_kpi: Optional[bool] = True, kpi_targets: Optional[dict] = None,
                 use_dcap: Optional[bool] = False, qc_domain: Optional[str] = None, qc_id: Optional[str] = None,
                 qc_project: Optional[str] = None, customers_list: Optional[list] = None,
                 report_comment: Optional[str] = None, sw_build: Optional[str] = None, topology: Optional[str] = None,
                 use_external_storage: Optional[bool] = False, download_path: Optional[str] = None,
                 use_testpackage: Optional[bool] = False, restore_to_target_sw: Optional[bool] = True,
                 l3_call_method: Optional[callable] = None, stop_test_after_fail: Optional[bool] = False,
                 artifactory_location: Optional[str] = "espoo2", package_suffix: Optional[str] = "A54",
                 synchronize_software_on_passive: Optional[bool] = False,
                 yaft_path: Optional[str] = "/home/ute/YAFT", virtualenv_dir: Optional[str] = None,
                 rollback_reverse_order: bool = False, detailed_console_log: bool = True, ru_update_sw: bool = False,
                 collect_passed_logs: int = 0, swconfig_modification: bool = True, hwf_migration_check: bool = True,
                 kpi_to_calculate: list = None, diagnostic_check: bool = False):
        super().__init__(nodes_details, test_nodes_details, iterations_per_node, report, calculate_kpi, kpi_targets,
                         use_dcap, qc_domain, qc_id, qc_project, customers_list, report_comment,
                         sw_build, topology, use_external_storage, download_path, use_testpackage, stop_test_after_fail,
                         artifactory_location, package_suffix, l3_call_method, synchronize_software_on_passive,
                         yaft_path, virtualenv_dir, detailed_console_log, ru_update_sw, collect_passed_logs,
                         swconfig_modification, hwf_migration_check, kpi_to_calculate, diagnostic_check)
        self.restore_to_target_sw = restore_to_target_sw
        self.l3_call_result = None
        self.rollback_reverse_order = rollback_reverse_order

    def test(self):
        self.run_iteration_precondition()
        self.failed_nodes = self.test_operation(None)
        self.report_results_to_uuf_dashboard()
        self.run_iteration_postcondition(None)
        self.verify_failed_nodes_after_iteration()
        if self.l3_call_method and not self.l3_call_result:
            raise IterationFailedError("Iteration Failed. L3 Call failed.")

    def test_operation(self, node):
        self.set_timestamp_reporting_and_kpi()
        self.software_update_test()
        self.software_rollback_test()
        return self.failed_nodes

    def software_rollback_test(self):
        with RobotWrapper("Software Rollback Test", "kw"):
            test_nodes = self.test_nodes[::-1] if self.rollback_reverse_order else self.test_nodes
            for node in test_nodes:
                self.rollback_sw(node)

    @wrapper_decorator
    def rollback_sw(self, node):
        self._rollback_sw(node)
        self.summary_operation(node, "rollback", self.failed_nodes_during_rollback)

    def _rollback_sw(self, test_node):
        self._set_current_logs_dir(test_node)
        self.multi_runner.start_log_tracing_all_nodes()
        if self.check_nodes_state_before_rollback(test_node):
            self.check_for_additional_snapshot()
            self.failed_nodes[test_node.node_alias].update(self.sw_rollback_operation(test_node))
        else:
            self.gather_mumin_logs_and_snapshot('rollback')
            self.failed_nodes[test_node.node_alias].update({test_node.node_alias})
            self.failed_nodes_during_rollback = {test_node.node_alias}

    @method_decorator()
    def sw_rollback_operation(self, node):
        node.logsverify.reset_check = False
        operation = "rollback"
        try:
            self.multi_runner.start_watching_alarms_on_all_nodes()
            self.gather_blackbox_and_set_reset_counter(operation)
            self.add_all_allowed_specific_faults(node)
            node.perform_rollback_and_wait_for_reload()
            self.get_latest_ims_file(node, operation)
            self.failed_nodes_during_rollback = self.verify_nodes_after_sw_change_operation(node, operation)
            return self.failed_nodes_during_rollback
        except Exception as e:
            test_logger(e, console=False)
            self.failed_nodes_during_rollback = {node.node_alias}
            node.btsverify.bts_fault_message += f"\n{str(e)}"
            return self.failed_nodes_during_rollback
        finally:
            self.remove_allowed_alarms_from_nodes(self.nodes, self.all_allowed_specific_faults)
            node.logsverify.reset_check = True
            if self.calculate_kpi:
                node.collect_infomodel_log_after_rollback(logs_dir=self.current_logs_dir)

    @method_decorator()
    def check_nodes_state_before_rollback(self, node, operation: str = "rollback"):
        try:
            node.verify_active_sw_version(node.target_sw + node.testpackage_prefix())
        except Exception as e:
            test_logger(e, "ERROR")
            return False
        return super().check_nodes_state_before_operation(node, operation)

    def run_iteration_postcondition(self, node):
        with RobotWrapper("Iteration Postcondition", "kw"):
            for node in self.test_nodes:
                self._postcondition(node)

    @wrapper_decorator
    def _postcondition(self, node):
        try:
            node.verify_active_sw_version(node.source_sw)
        except WrongSwVersion:
            node.perform_rollback_and_wait_for_reload()
            node.start_watching_alarms()
            node.verify_node_bts_state()

    def restore_target_sw(self):
        try:
            for node in self.test_nodes:
                self.setup_admin_connections()
                self.current_logs_dir = os.path.join(self.log_dir, "Test_Teardown", f"TEST_ON_{node.node_alias}")
                failed_nodes = self.update_sw_operation(node)
                if failed_nodes:
                    self.gather_mumin_logs_and_snapshot("update")
                    if node.btslog.running:
                        self.stop_test_log_tracing(f"{self.current_logs_dir}/update")
                    raise TestFailedOnTeardownError
        finally:
            self.teardown_nodes()

    def test_teardown(self):
        self.current_logs_dir = f"{self.log_dir}/Test_Teardown"
        try:
            if self.restore_to_target_sw:
                self.use_testpackage = False
                self.restore_target_sw()
        finally:
            super().test_teardown()

    def run_test(self):
        try:
            self.run_setup()
            self.execute_test_in_loop()
            if any(nodes_results != "passed" for nodes_results in self.test_results.values()):
                raise TestExecutionFailed()
        except (FatalError, RecoveryAttemptFailedError):
            self.restore_to_target_sw = False
            raise
        finally:
            if self.report_to_rp:
                self.report_results()
            self.run_teardown()

    @method_decorator()
    def run_kpi_calculation(self, node):
        try:
            test_logger("Calculating OAM KPI")
            self.kpi.kpi_calc.serial_console_connected = len(node.btsverify.cells_verifier.serial_console_cells) > 0
            self.kpi.set_end_timestamp_for_kpi_calculation()
            for operation in ["update", "rollback"]:
                if operation == "update":
                    self.select_upgrade_kpi(node)
                else:
                    self.kpi.kpi_names = ["kpi13b"]
                    test_logger(f"Selected KPI for rollback calculation : {self.kpi.kpi_names}", "info")
                self.kpi.calculate_proper_oam_kpi(f"{self.current_logs_dir}/oam_kpis/{operation}/")
        except Exception as e:
            test_logger(e, console=False)
            test_logger("KPI Calculation failed", "error")
        finally:
            node.calculate_provision_download_kpi = False
            if self.report_to_rp:
                result = "failed" if self.failed_nodes[node.node_alias] or self.precheck_failed else "passed"
                self.test_reporter.report_result_to_uuf_dashboard(node, result,
                                                                  self.kpi.get_uuf_kpi(self.uuf_case_type),
                                                                  self.current_iteration,
                                                                  self.kpi.get_kpi_results())
                self.kpi.clear_kpi_results()
